export interface FeatureFlag {
  key: string;
  enabled: boolean;
  rollout: number;
}

export const featureFlags: Record<string, FeatureFlag> = {
  'new-checkout': { key: 'new-checkout', enabled: true, rollout: 1.0 },
  'dark-mode': { key: 'dark-mode', enabled: false, rollout: 0.25 },
};

export function isFlagEnabled(key: string): boolean {
  const flag = featureFlags[key];
  return flag !== undefined && flag.enabled && flag.rollout >= Math.random();
}

import { useEffect, useState } from 'react';
import { isFlagEnabled } from '../config/flags';

export function useFeatureFlag(key: string): boolean {
  const [enabled, setEnabled] = useState(() => isFlagEnabled(key));

  useEffect(() => {
    setEnabled(isFlagEnabled(key));
  }, [key]);

  return enabled;
}

import type { ReactNode } from 'react';
import { useFeatureFlag } from '../hooks/useFeatureFlag';

export interface FeatureGateProps {
  flag: string;
  children: ReactNode;
  fallback?: ReactNode;
}

export function FeatureGate({ flag, children, fallback = null }: FeatureGateProps): ReactNode {
  const enabled = useFeatureFlag(flag);
  return enabled ? children : fallback;
}
